import re
import os
import torch

from dotenv import load_dotenv
load_dotenv()
SYSTEM_PROMPT = os.getenv("SYSTEM_PROMPT")

def formatting_func(sample):
    '''Formats data for completion only loss classification tasks.'''
    return {
        "prompt": (
            f"{SYSTEM_PROMPT}\n" f"User query: {sample['query']}\n"
            "Classification: "
        ),
        "completion": str(sample['label'])
    }

def extract_label(generated_text):
    '''Extracts the '0' or '1' generated by the EB gaurdian model.'''
    text = generated_text.strip()
    match = re.match(r"-?\d+", text)
    return match.group(0) if match else None

def evaluate_model(model, tokenizer, dataset, batch_size=16):
    '''Evaluates the accuracy of a classification model.'''
    formatted_data = dataset.map(
        formatting_func,
        remove_columns=dataset.column_names
        )

    if tokenizer.tokenizer.pad_token is None:
        tokenizer.tokenizer.pad_token = tokenizer.tokenizer.eos_token
    tokenizer.tokenizer.padding_side = "left"

    predictions = []
    prompts = formatted_data["prompt"]
    for i in range(0, len(prompts), batch_size):
        batch_prompts = prompts[i:i + batch_size]
        inputs = tokenizer(text=batch_prompts, return_tensors="pt", padding=True).to(model.device)
        with torch.no_grad():
            out = model.generate(
                **inputs,
                max_new_tokens=8,
                do_sample=False,
                pad_token_id=tokenizer.pad_token_id
            )
        input_len = inputs["input_ids"].shape[1]
        generated_batch = tokenizer.batch_decode(
            out[:, input_len:], skip_special_tokens=True
        )
        predictions.extend(extract_label(g) for g in generated_batch)
    
    true_labels = formatted_data["completion"]
    correct = sum(p == t for p, t in zip(predictions, true_labels))

    print(f"Accuracy: {correct}/{len(true_labels)} = {correct/len(true_labels):.4f}")